UPDATE TRD_PRODUCT_DEAL_PRE
SET TRADE_STATUS = #{REVOKE_TRADE_STATUS},
    IS_CANCEL = #{isCancel},
    UPDATE_USER = #{user},
    UPDATE_TIME = #{time,jdbcType=DATE}
WHERE TOTLE_TRADE_ID = #{bizCode, jdbcType = VARCHAR}

