select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL
where
    (TOTLE_TRADE_ID = #{totleTradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{totleTradeId,jdbcType=VARCHAR})
    and
    (IS_CANCEL = #{YES_NO_YES,jdbcType=VARCHAR}
    or TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
    )
